-- V90.fk: Reliability Governance Learning Execution & Benefit Realization
-- Schema target: 237
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_execution (execution_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, recommendation_id TEXT, recommendation_type TEXT NOT NULL, finding TEXT NOT NULL, planned_improvement TEXT NOT NULL, owner_user_id TEXT, due_date DATE, status TEXT NOT NULL DEFAULT 'REQUESTED', execution_note TEXT, evidence_note TEXT, completed_by TEXT, completed_at TIMESTAMP, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_benefit (benefit_id TEXT PRIMARY KEY, execution_id TEXT NOT NULL UNIQUE, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, baseline_score NUMERIC NOT NULL DEFAULT 0, followup_score NUMERIC NOT NULL DEFAULT 0, score_delta NUMERIC NOT NULL DEFAULT 0, outcome TEXT NOT NULL DEFAULT 'PENDING', finding TEXT NOT NULL, evidence_note TEXT NOT NULL, reviewed_by TEXT, reviewed_at TIMESTAMP, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_execution_close (close_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, execution_count INTEGER NOT NULL DEFAULT 0, open_execution_count INTEGER NOT NULL DEFAULT 0, completed_count INTEGER NOT NULL DEFAULT 0, effective_count INTEGER NOT NULL DEFAULT 0, learning_benefit_score NUMERIC NOT NULL DEFAULT 0, closed_by TEXT NOT NULL, closure_note TEXT, closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,period_key));
CREATE INDEX IF NOT EXISTS ix_rel_gov_learning_exec_scope ON maintenance_reliability_governance_learning_execution(organization_id,entity_id,period_key,status);
CREATE INDEX IF NOT EXISTS ix_rel_gov_learning_benefit_scope ON maintenance_reliability_governance_learning_benefit(organization_id,entity_id,period_key,outcome);
